using System;
using WoWProbe;
class CampaignEngineTests
{
    static int passed,failed;static void Assert(bool b){if(!b)throw new Exception("assertion failed");}static void Test(string n,Action a){try{a();passed++;Console.WriteLine("PASS "+n);}catch(Exception e){failed++;Console.WriteLine("FAIL "+n+": "+e.Message);}}
    static int Main()
    {
        Test("campaign starts farm and snapshots an owned validated plan",delegate{var p=CampaignFixtures.Plan();var e=new CampaignEngine(p);p.FarmRoute.MapId++;var o=CampaignFixtures.Sample();Assert(e.Step(o,0).Action!=OperationAction.Stop&&e.Status.StartsWith("Farm"));});
        Test("death preempts bag-full while preserving original farm index",delegate{var p=CampaignFixtures.Plan();p.StartIndex=2;var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;o.Farm.BagFull=true;o.FreeSlots=0;o.ReleaseVisible=o.ReleaseEnabled=true;var c=e.Step(o,0);Assert(e.Status.StartsWith("Recovery")&&e.SavedFarmIndex==2&&c.Action==OperationAction.None);CampaignFixtures.Next(o);c=e.Step(o,200);Assert(c.Action==OperationAction.LeftClick&&c.Purpose==OperationPurpose.Release&&e.SavedFarmIndex==2);});
        Test("one death frame and repeated frame never release",delegate{var e=new CampaignEngine(CampaignFixtures.Plan());var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;o.ReleaseVisible=o.ReleaseEnabled=true;Assert(e.Step(o,0).Action==OperationAction.None);Assert(e.Step(o,1000).Action!=OperationAction.LeftClick);});
        Test("full capacity is confirmed for three seconds before vendor interruption",delegate{var p=CampaignFixtures.Plan();p.StartIndex=1;var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();o.FreeSlots=0;o.Farm.BagFull=true;Assert(e.Step(o,0).Action==OperationAction.None);CampaignFixtures.Next(o);Assert(e.Step(o,2999).Action==OperationAction.None);CampaignFixtures.Next(o);var c=e.Step(o,3000);Assert(e.Status.StartsWith("Vendor")&&e.SavedFarmIndex==1&&c.Action!=OperationAction.Stop);});
        Test("disabled recovery or merchant modes stop without unexpected inputs",delegate{var p=CampaignFixtures.Plan();p.Settings.EnableRecovery=false;var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;Assert(e.Step(o,0).Action==OperationAction.Stop);p=CampaignFixtures.Plan();p.Settings.EnableVendor=false;e=new CampaignEngine(p);o=CampaignFixtures.Sample();o.FreeSlots=0;o.Farm.BagFull=true;e.Step(o,0);CampaignFixtures.Next(o);Assert(e.Step(o,3000).Action==OperationAction.Stop);});
        Test("manual stop is latched even if death or bags change",delegate{var e=new CampaignEngine(CampaignFixtures.Plan());e.Stop("F12");var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;Assert(e.Step(o,0).Action==OperationAction.Stop&&e.LastReason=="F12");});
        Test("unknown paired data map and backwards clock stop campaign",delegate{var e=new CampaignEngine(CampaignFixtures.Plan());var o=CampaignFixtures.Sample();o.Fresh=false;Assert(e.Step(o,0).Action==OperationAction.Stop);e=new CampaignEngine(CampaignFixtures.Plan());o=CampaignFixtures.Sample();o.Farm.MapId++;Assert(e.Step(o,0).Action==OperationAction.Stop);e=new CampaignEngine(CampaignFixtures.Plan());o=CampaignFixtures.Sample();e.Step(o,100);Assert(e.Step(o,99).Action==OperationAction.Stop);});
        Test("checkpoint binds whole plan and records pending interruption",delegate{var p=CampaignFixtures.Plan();var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();o.Farm.PlayerDead=true;o.Farm.Health=0;e.Step(o,0);var c=e.CurrentCheckpoint;Assert(c.PlanFingerprint==p.Fingerprint()&&c.Interrupted&&!c.Completed&&c.FarmIndex==e.SavedFarmIndex);});
        Test("optional portrait verification requires this frame and target rather than stale matches",delegate{foreach(int variant in new[]{0,1,2,3}){var p=CampaignFixtures.Plan();p.Settings.RequirePortraitMatch=true;var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();o.Farm.TargetExists=o.Farm.TargetIdentityKnown=o.Farm.NameHashKnown=o.Farm.AttackabilityKnown=o.Farm.TargetCanAttack=o.Farm.TargetDeadKnown=o.Farm.RangeKnown=o.Farm.TargetInRange=true;o.Farm.TargetToken=303;o.Farm.TargetNameHash=TargetCatalog.HashName("演示野兽");o.Farm.TargetHealth=100;o.Farm.RangeSlot=1;o.PortraitCheckKnown=variant!=0;o.PortraitMatch=variant!=1;o.PortraitCheckSequence=variant==2?0:o.Sequence;o.PortraitCheckTargetToken=o.Farm.TargetToken;var c=e.Step(o,0);Assert((c.Action==OperationAction.Stop)==(variant!=3));}});
        Test("closing a completed campaign retains its completed checkpoint",delegate{var p=CampaignFixtures.Plan();p.Settings.EnableRecovery=p.Settings.EnableVendor=false;p.FarmRoute.Points=new System.Collections.Generic.List<Waypoint>{new Waypoint{X=.5,Y=.5},new Waypoint{X=.501,Y=.5}};var e=new CampaignEngine(p);var o=CampaignFixtures.Sample();for(int i=0;i<10&&!e.Completed;i++){CampaignFixtures.Next(o);e.Step(o,i*200);}Assert(e.Completed);e.Stop("window close");Assert(e.Completed&&e.CurrentCheckpoint.Completed&&e.CurrentCheckpoint.FarmIndex==2);});
        Console.WriteLine("Campaign engine tests: "+passed+" passed, "+failed+" failed");return failed==0?0:1;
    }
}
